def generic_transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); up=down=0
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=2 or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                rr,cc=stack.pop(); cells.append((rr,cc))
                for nr,nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0<=nr<h and 0<=nc<w and grid[nr][nc]==2 and (nr,nc) not in seen:
                        seen.add((nr,nc)); stack.append((nr,nc))
            rs=[x for x,y in cells]; cs=[y for x,y in cells]
            if len(cells)==4 and max(rs)-min(rs)==1 and max(cs)-min(cs)==2:
                top_count=sum(1 for rr,cc in cells if rr==min(rs))
                if top_count==1: up+=1
                elif top_count==3: down+=1
    out=[[0]*6 for _ in range(3)]
    for n,value,base in ((up,3,0),(down,1,3)):
        for i in range(min(n,4)):
            out[0 if i%2==0 else 2][base+(i//2)*2]=value
    return out
